// Current local time for the prompt (added 2026-10-01): without it the model guessed and answered
// "what time is it" with a location. Computed per request in the household's time zone.
const tz = 'Europe/Berlin';
const nowD = new Date();
const clockTime = nowD.toLocaleTimeString('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit' });
const clockDate = nowD.toLocaleDateString('en-GB', { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const clockLine = `Current local time: ${clockTime} on ${clockDate} (time zone Europe/Berlin).\n` +
  `If the user asks for the time, the date or the day, answer with exactly these values in one short, plain spoken sentence (no formatting, no time zone unless asked).\n\n`;
const shortterm = $('Load Short-Term Memory').all().map(i => i.json).filter(j => j && j.role).slice(-12);
const longterm = $('Load Long-Term Memory').all().map(i => i.json).filter(j => j && j.summary).slice(-3);
const longSummary = longterm.map(l => l.summary).join('\n');
const shortHistory = shortterm.map(m => `${m.role}: ${m.text}`).join('\n');
const userPrompt = $('Parse Classification').item.json.prompt;
return [{
  fullPrompt: `${clockLine}Here is what I remember long-term:\n${longSummary}\n\nRecent conversation:\n${shortHistory}\nUser: ${userPrompt}\nAssistant:`,
  userPrompt,
  device_id: $('Parse Classification').item.json.device_id
}];

