// Plain speech for HA's TTS. Until 2026-10-13 only bold and headings were removed, so tables,
// emoji and arrows were read out. Everything a voice cannot say goes.
// Overheard talk gets the shortest thing a voice can say (flag set in "Assemble Prompt with Context (chat)", which
// has not run when Home Assistant answered instead).
let overheard = false;
try { overheard = !!$('Assemble Prompt with Context (chat)').first().json.overheard; } catch (e) {}
const spoken = overheard ? 'Mm.' : String($json.response || '')
  .replace(/```[\s\S]*?```/g, ' ')
  .replace(/^\s*\|?[\s:|-]{3,}\|?\s*$/gm, ' ')          // table rules
  .replace(/\|/g, ', ')
  .replace(/<br\s*\/?>/gi, ' ')
  .replace(/\*\*|__|`|\*|_/g, '')
  .replace(/^\s*#{1,6}\s+/gm, '')
  .replace(/^\s*(?:[-•→➔]|\d+[.)])\s+/gm, '')
  .replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}→➔←↑↓]/gu, '')
  .replace(/\s*\n+\s*/g, ' ')
  .replace(/(?:,\s*){2,}/g, ', ')
  .replace(/\s{2,}/g, ' ')
  .trim() || "Sorry, I didn't catch that.";
// A hard limit the model cannot talk its way past (2026-10-13: asked for five sentences, a story
// came back with seven and was cut mid-word by the token limit). Whole sentences only, at most
// six of them and about seventy words.
function capped(text) {
  // A sentence ends at . ! ? … followed by a space, so "7.5 degrees" stays whole.
  const sentences = text.split(/(?<=[.!?…]["”’)]*)\s+/).filter(Boolean);
  const whole = /[.!?…]["”’)]*$/.test(text) ? sentences : sentences.slice(0, -1);   // drop a cut-off tail
  const kept = [];
  let wordCount = 0;
  for (const s of (whole.length ? whole : sentences)) {
    const n = s.trim().split(/\s+/).length;
    if (kept.length && (kept.length >= 6 || wordCount + n > 70)) break;
    kept.push(s.trim());
    wordCount += n;
  }
  return kept.join(' ');
}
const model = $json.model || 'qwen2.5:7b-instruct-q4_K_M';
return [{
  model,
  created_at: new Date().toISOString(),
  message: { role: 'assistant', content: overheard ? spoken : capped(spoken) },
  done: true,
  done_reason: 'stop'
}];

