// but fall back to top-level fields too in case that ever changes.
const src = $json.body || $json;
return [{
  prompt: (src.prompt || src.text || '').toString().trim(),
  device_id: src.device_id || 'media_player.living_room_speaker',
  ha_user_id: src.user_id || src.ha_user_id || 'unknown'
}];

const content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';
const raw = content.replace(/[^A-Za-z]+/g, ' ').trim().toUpperCase(); // strip markdown like **HOME**
const input = $('Normalize Input').item.json;
const prompt = (input.prompt || '').toLowerCase();

const homeKeywords = [
  'turn on', 'turn off', 'switch on', 'switch off', 'light', 'lights',
  'lock', 'unlock', 'thermostat', 'temperature', 'dim', 'brightness',
  'alarm', 'scene', 'lamp', 'plug', 'fan', 'blinds', 'curtain', 'garage',
  'volume', 'play music', 'pause', 'stop music'
];
const hasHomeKeyword = homeKeywords.some(k => prompt.includes(k));

// GENERAL is the safe default. Only ever classify as HOME when there's an
// actual device-control keyword in the prompt AND the LLM agrees — this
// caught a live bug where a rambling conversational test question ('How
// about now? Can you understand my voice?...') got classified HOME by the
// LLM alone, sending it into HA's device-matching intent parser and
